tool_input_args.value:
awk -F',' '
NR>1 && $6 ~ /^2026-0[789]/ {
  # All deals
  if ($2=="James Okafor") { james_all += $5; james_n++ }
  if ($2=="Sofia Delgado") { sofia_all += $5; sofia_n++ }

  # Won deals only
  if ($7=="won") {
    total_won += $5; won_count++
    if ($2=="James Okafor") { james_won += $5 }
    if ($2=="Sofia Delgado") { sofia_won += $5 }
    if ($3=="South") { south_won += $5 }
  }
  if ($7=="pending") { pending += $5; pending_count++ }
  if ($7!="") { all_count++ }
}
END {
  print "--- Won deals ---"
  print "Total won: $" total_won " (" won_count " deals)"
  print "James Okafor won: $" james_won
  print "Sofia Delgado won: $" sofia_won
  print "South region won: $" south_won
  print ""
  print "--- Pending ---"
  print "Pending total: $" pending " (" pending_count " deals)"
  print ""
  print "--- Opportunities ---"
  print "Total deals: " all_count
  print "Win rate: " (won_count/all_count)*100 "%"
}' data/sales_q3.csv
